/**
 * The flow expression language.
 *
 * Expressions are plain JSON trees, so flows stay data: they can be stored,
 * diffed, generated by tools and validated without running code. The
 * language is closed (no user functions, no loops, no I/O), total (every
 * expression evaluates in bounded time to a value or to "unknown") and
 * three-valued: reading a fact that is not yet known yields unknown instead
 * of a guess, and the facts that caused it are reported so the engine knows
 * what to ask for next.
 *
 * Examples:
 *   {"eq": [{"fact": "tripType"}, "round"]}
 *   {"and": [{"known": "email"}, {"gte": [{"fact": "guests"}, 1]}]}
 *   {"if": [{"fact": "express"}, {"result": "quote", "path": ["fast"]}, null]}
 *
 * Strings, numbers, booleans and null are literals. Objects and arrays must
 * be written with `obj`, `list` or `lit` so a literal can never be mistaken
 * for an operator.
 *
 * `{"expr": "fact.tripType == 'round'"}` is the same language written in
 * Facet's expression syntax; it compiles to the tree form (expr-text.ts).
 *
 * Lists are processed with `map`, `filter`, `some` and `every`, which take
 * `[list, expression]` and evaluate the expression once per element, read
 * there as `{"item": [path...]}`; `sum` adds a list of numbers. Work spent on
 * lists and the size of built values are capped, so evaluation stays bounded.
 *
 * Collections: `{"fact": "c"}` reads a collection as
 * `[{id, ...fields}]`, known once the list is settled and every field the
 * read needs is known on every item. Where an expression belongs to one item
 * (a per-item step, a per-item action, a field's derive and checks),
 * `{"item": ["f"]}` outside any list operation reads that item's field.
 * `{"items": "c"}` (text `fact.c | items`) gives the list's current rows as
 * they stand, for views only.
 */

import { BLOB_REF_KEY, findBlobRefs } from "@aaply/action-contract";
import { DiagnosticBag } from "./diagnostics.js";
import { textToExpr } from "./expr-text.js";
import { checkJson, cloneJson, isJsonObject, type JsonPrimitive, type JsonValue, type PathSegment } from "./json.js";

export type EnvName = "locale" | "timezone" | "environment";

export type Expr =
  | JsonPrimitive
  | { lit: JsonValue }
  | { fact: string; path?: PathSegment[] }
  | { result: string; path?: PathSegment[] }
  | { payload: PathSegment[] }
  | { value: PathSegment[] }
  | { resource: PathSegment[] }
  | { env: EnvName }
  | { now: true }
  | { known: string }
  | { failed: string }
  | { not: Expr }
  | { and: Expr[] }
  | { or: Expr[] }
  | { eq: [Expr, Expr] }
  | { ne: [Expr, Expr] }
  | { lt: [Expr, Expr] }
  | { lte: [Expr, Expr] }
  | { gt: [Expr, Expr] }
  | { gte: [Expr, Expr] }
  | { in: [Expr, Expr] }
  | { if: [Expr, Expr, Expr] }
  | { coalesce: Expr[] }
  | { len: Expr }
  | { add: Expr[] }
  | { mul: Expr[] }
  | { sub: [Expr, Expr] }
  | { div: [Expr, Expr] }
  | { concat: Expr[] }
  | { lower: Expr }
  | { trim: Expr }
  | { obj: Record<string, Expr> }
  | { list: Expr[] }
  | { ms: Expr }
  /** `[list, expression]`; the expression reads each element with `item`. */
  | { map: [Expr, Expr] }
  | { filter: [Expr, Expr] }
  | { some: [Expr, Expr] }
  | { every: [Expr, Expr] }
  | { sum: Expr }
  /**
   * The current element inside map, filter, some or every (the innermost
   * one); outside them, where an expression belongs to one item, that item.
   */
  | { item: PathSegment[] }
  /** A collection's rows as they stand, valid values only (views only). */
  | { items: string }
  /** The text form in Facet's expression syntax, e.g. "fact.count >= 1"; see expr-text.ts. */
  | { expr: string }
  /** A fragment's parameter; only in fragments, where expanding an include replaces it with its binding. */
  | { param: string };

/** Where an expression appears decides which references it may use. */
export type ExprScope = "payload" | "value" | "resource" | "result";

export type Cmp = "eq" | "ne" | "lt" | "lte" | "gt" | "gte";
export type ListOp = "map" | "filter" | "some" | "every";

export type Node =
  | { k: "lit"; v: JsonValue }
  /**
   * `fields` is set on reads of a collection: the item fields the read needs
   * (`[]` for membership only, `"*"` for all of them).
   */
  | { k: "fact"; name: string; path: PathSegment[]; fields?: readonly string[] | "*" }
  | { k: "result"; name: string; path: PathSegment[] }
  | { k: "payload"; path: PathSegment[] }
  | { k: "value"; path: PathSegment[] }
  | { k: "resource"; path: PathSegment[] }
  | { k: "env"; name: EnvName }
  | { k: "now" }
  | { k: "known"; name: string }
  | { k: "failed"; name: string }
  | { k: "not"; a: Node }
  | { k: "and" | "or" | "coalesce" | "add" | "mul" | "concat" | "list"; items: Node[] }
  | { k: Cmp | "in" | "sub" | "div"; a: Node; b: Node }
  | { k: "if"; c: Node; t: Node; e: Node }
  | { k: "len" | "lower" | "trim" | "ms" | "sum"; a: Node }
  /** `a` is the list, `b` is evaluated per element. */
  | { k: ListOp; a: Node; b: Node }
  | { k: "item"; path: PathSegment[] }
  /** The field `path[0]` of the item the expression belongs to (or its `id`). */
  | { k: "self"; path: PathSegment[] }
  | { k: "items"; name: string }
  | { k: "obj"; entries: [string, Node][] };

/** The direct sub-expressions of a node. */
export function nodeChildren(node: Node): Node[] {
  switch (node.k) {
    case "if":
      return [node.c, node.t, node.e];
    case "obj":
      return node.entries.map(([, n]) => n);
    default:
      if ("items" in node) return node.items;
      if ("b" in node) return [node.a, node.b];
      if ("a" in node) return [node.a];
      return [];
  }
}

/** Static references made by an expression. */
export interface Reads {
  facts: Set<string>;
  results: Set<string>;
  /** Fields of the expression's own item that it reads (`item.f` outside list operations). */
  self?: Set<string>;
  /** Collections read as values, with the fields each read needs. */
  lists?: Map<string, Set<string> | "*">;
}

export function emptyReads(): Reads {
  return { facts: new Set(), results: new Set() };
}

export function mergeReads(into: Reads, from: Reads): Reads {
  for (const f of from.facts) into.facts.add(f);
  for (const r of from.results) into.results.add(r);
  if (from.self && from.self.size > 0) {
    into.self ??= new Set();
    for (const f of from.self) into.self.add(f);
  }
  if (from.lists) {
    for (const [name, fields] of from.lists) addListRead(into, name, fields);
  }
  return into;
}

function addListRead(into: Reads, name: string, fields: ReadonlySet<string> | readonly string[] | "*"): void {
  into.lists ??= new Map();
  const prev = into.lists.get(name);
  if (prev === "*" || fields === "*") {
    into.lists.set(name, "*");
    return;
  }
  const set = prev ?? new Set<string>();
  for (const f of fields) set.add(f);
  into.lists.set(name, set);
}

export const MAX_EXPR_DEPTH = 32;
export const MAX_EXPR_NODES = 512;

/** The names `{"env": ...}` reads (frozen). */
export const ENV_NAMES = Object.freeze(["locale", "timezone", "environment"] as const) satisfies readonly EnvName[];

/**
 * The operators of the expression language, by how they take their operands
 * (frozen; the parser reads its sets from here): `unary` one expression,
 * `binary` and `list` a pair (`list`: a list and an expression per element),
 * `ternary` three, `variadic` a list of operands (at least one, except the
 * operators in `emptyOk`), `leaf` a name, path or value, `record` an object
 * of expressions and `text` the text form. `path` may sit beside the
 * operators in `withPath`. `param` is not here: it exists only in fragments.
 */
export const EXPR_OPERATORS = Object.freeze({
  unary: Object.freeze(["not", "len", "lower", "trim", "ms", "sum"] as const),
  binary: Object.freeze(["eq", "ne", "lt", "lte", "gt", "gte", "in", "sub", "div"] as const),
  ternary: Object.freeze(["if"] as const),
  variadic: Object.freeze(["and", "or", "coalesce", "add", "mul", "concat", "list"] as const),
  list: Object.freeze(["map", "filter", "some", "every"] as const),
  leaf: Object.freeze(["lit", "fact", "result", "payload", "value", "resource", "item", "items", "env", "now", "known", "failed"] as const),
  record: Object.freeze(["obj"] as const),
  text: Object.freeze(["expr"] as const),
  emptyOk: Object.freeze(["list", "concat"] as const),
  withPath: Object.freeze(["fact", "result"] as const),
});

const UNARY = new Set<string>(EXPR_OPERATORS.unary);
const BINARY = new Set<string>(EXPR_OPERATORS.binary);
const VARIADIC = new Set<string>(EXPR_OPERATORS.variadic);
const LIST_OPS = new Set<string>(EXPR_OPERATORS.list);
const EMPTY_OK = new Set<string>(EXPR_OPERATORS.emptyOk);
const WITH_PATH = new Set<string>(EXPR_OPERATORS.withPath);
const OPERATORS = new Set<string>([
  ...UNARY, ...BINARY, ...VARIADIC, ...LIST_OPS,
  ...EXPR_OPERATORS.text, ...EXPR_OPERATORS.leaf, ...EXPR_OPERATORS.ternary, ...EXPR_OPERATORS.record,
]);
/**
 * An expression never writes a file reference (an object with a `$blob` key)
 * itself, in a `lit` or as an `obj` key: a reference a definition names was
 * vouched for by nobody, and would reach a performer's signed input or a
 * view's URL as if a person had given it (ADR-0008).
 */
const BLOB_LITERAL = "flow/blob-literal";
const BLOB_LITERAL_MESSAGE = "a definition cannot name a file itself; a file reference comes from a person's input (a payload or a fact) or an action's result";
const OBJECT_HINT = '; to write an object, use {"lit": {...}} for a fixed value or {"obj": {...}} to build one from expressions';

export interface ParseOptions {
  /** Extra reference kinds allowed here (payload, value, resource). */
  scopes?: ReadonlySet<ExprScope>;
  /** `{"now": true}` is refused where a changing value would cause churn (action input, derived facts). */
  allowNow?: boolean;
  /** Fact and result references are refused where only frozen data is safe (compensation input). */
  allowState?: boolean;
  /** Collections and their field names, so reads of them are recognised and checked. */
  collections?: ReadonlyMap<string, ReadonlySet<string>>;
  /** The collection whose item the expression belongs to: `item.f` outside list operations reads it. */
  itemOf?: string;
  /** `items` is allowed (view inputs only). */
  allowItems?: boolean;
}

interface ParseState {
  bag: DiagnosticBag;
  scopes: ReadonlySet<ExprScope>;
  allowNow: boolean;
  allowState: boolean;
  nodes: number;
  reads: Reads;
  /** How many list operations enclose this point, so `item` has an element to read. */
  itemDepth: number;
  tooDeep: boolean;
  collections: ReadonlyMap<string, ReadonlySet<string>>;
  itemOf: string | undefined;
  allowItems: boolean;
}

const NO_COLLECTIONS: ReadonlyMap<string, ReadonlySet<string>> = new Map();

function isPath(v: unknown): v is PathSegment[] {
  return (
    Array.isArray(v) &&
    v.length <= 16 &&
    v.every((s) => (typeof s === "string" && s.length <= 128) || (typeof s === "number" && Number.isInteger(s) && s >= 0))
  );
}

/**
 * Parses and checks an expression. Returns the compiled node and its static
 * reads, or `null` (with diagnostics in `bag`) when the expression is
 * malformed. Names are not resolved here; the flow validator does that.
 */
export function parseExpr(raw: unknown, path: PathSegment[], bag: DiagnosticBag, options: ParseOptions = {}): { node: Node; reads: Reads } | null {
  const state: ParseState = {
    bag,
    scopes: options.scopes ?? new Set(),
    allowNow: options.allowNow ?? true,
    allowState: options.allowState ?? true,
    nodes: 0,
    reads: emptyReads(),
    itemDepth: 0,
    tooDeep: false,
    collections: options.collections ?? NO_COLLECTIONS,
    itemOf: options.itemOf,
    allowItems: options.allowItems ?? false,
  };
  const before = bag.items.length;
  const node = parse(raw, path, state, 0);
  if (!node || bag.items.slice(before).some((d) => d.severity === "error")) return null;
  if (state.collections.size > 0) {
    for (const unknownField of annotateListReads(node, state.collections, state.reads)) {
      bag.error("flow/unknown-fact", path, `unknown field "${unknownField.field}" of collection "${unknownField.collection}"`);
    }
    if (bag.items.slice(before).some((d) => d.severity === "error")) return null;
  }
  return { node, reads: state.reads };
}

/**
 * Field analysis: works out which item fields each read of a collection
 * needs, sets `fields` on the read and records it in `reads.lists`. Only
 * reads whose elements cannot escape are narrowed: `len(c)` needs none,
 * `some`, `every` and `map` over `c` need the fields their expression reads
 * of the element, `len(filter(c, p))` the fields `p` reads; anything else,
 * or an expression that uses the whole element, needs every field (`"*"`).
 */
function annotateListReads(root: Node, collections: ReadonlyMap<string, ReadonlySet<string>>, reads: Reads): Array<{ collection: string; field: string }> {
  const problems: Array<{ collection: string; field: string }> = [];
  const isList = (n: Node): n is Extract<Node, { k: "fact" }> => n.k === "fact" && n.path.length === 0 && collections.has(n.name);
  const fieldsOf = (body: Node, collection: string): string[] | "*" => {
    const declared = collections.get(collection)!;
    const out = new Set<string>();
    let star = false;
    const walk = (n: Node, depth: number) => {
      if (n.k === "item" && depth === 0) {
        const f = n.path[0];
        if (typeof f !== "string") star = true;
        else if (f !== "id") {
          if (!declared.has(f)) problems.push({ collection, field: f });
          out.add(f);
        }
        return;
      }
      if (n.k === "map" || n.k === "filter" || n.k === "some" || n.k === "every") {
        walk(n.a, depth);
        walk(n.b, depth + 1);
        return;
      }
      for (const child of nodeChildren(n)) walk(child, depth);
    };
    walk(body, 0);
    return star ? "*" : [...out].sort();
  };
  const visit = (n: Node) => {
    if (n.k === "len") {
      if (isList(n.a)) n.a.fields ??= [];
      else if (n.a.k === "filter" && isList(n.a.a)) n.a.a.fields ??= fieldsOf(n.a.b, n.a.a.name);
    } else if ((n.k === "some" || n.k === "every" || n.k === "map") && isList(n.a)) {
      n.a.fields ??= fieldsOf(n.b, n.a.name);
    }
    if (n.k === "fact" && collections.has(n.name)) {
      n.fields ??= "*";
      addListRead(reads, n.name, n.fields);
    }
    for (const child of nodeChildren(n)) visit(child);
  };
  visit(root);
  return problems;
}

function failAt(st: ParseState, at: PathSegment[], code: string, message: string): null {
  st.bag.error(code, at, message);
  return null;
}

function parse(raw: unknown, path: PathSegment[], st: ParseState, depth: number): Node | null {
  st.nodes++;
  if (st.nodes > MAX_EXPR_NODES) {
    if (st.nodes === MAX_EXPR_NODES + 1) st.bag.error("flow/expr-too-large", path, `expression has more than ${MAX_EXPR_NODES} nodes`);
    return null;
  }
  if (depth > MAX_EXPR_DEPTH) {
    if (!st.tooDeep) st.bag.error("flow/expr-too-deep", path, `expression is nested deeper than ${MAX_EXPR_DEPTH}`);
    st.tooDeep = true;
    return null;
  }
  if (raw === null || typeof raw === "string" || typeof raw === "boolean") return { k: "lit", v: raw };
  if (typeof raw === "number") {
    if (!Number.isFinite(raw)) {
      st.bag.error("flow/expr-invalid", path, "numbers must be finite");
      return null;
    }
    return { k: "lit", v: raw };
  }
  if (Array.isArray(raw)) {
    st.bag.error("flow/expr-invalid", path, 'arrays must be written as {"list": [...]} or {"lit": [...]}');
    return null;
  }
  if (!isJsonObject(raw)) {
    st.bag.error("flow/expr-invalid", path, "expression must be JSON");
    return null;
  }
  const keys = Object.keys(raw);
  const opKeys = keys.filter((k) => k !== "path");
  const mainKey = opKeys[0];
  if (mainKey === undefined || opKeys.length !== 1) {
    const hint = opKeys.length === 0 || opKeys.some((k) => !OPERATORS.has(k)) ? OBJECT_HINT : "";
    st.bag.error("flow/expr-invalid", path, `expression object must have exactly one operator, got {${keys.join(", ")}}${hint}`);
    return null;
  }
  const arg = raw[mainKey];
  const at = [...path, mainKey];
  const bad = (message: string): null => {
    st.bag.error("flow/expr-invalid", at, message);
    return null;
  };
  if (keys.includes("path") && !WITH_PATH.has(mainKey)) return bad(`"path" is only allowed with "fact" or "result"`);

  switch (mainKey) {
    case "expr": {
      if (typeof arg !== "string") return bad("expr takes the expression as text");
      const text = textToExpr(arg);
      if (!text.ok) {
        st.bag.error("flow/expr-syntax", at, `${text.message} (at character ${text.offset + 1})`);
        return null;
      }
      // The wrapper is not a node of its own.
      st.nodes--;
      return parse(text.expr, at, st, depth);
    }
    case "lit": {
      const issue = checkJson(arg);
      if (issue) return bad(`literal is not JSON: ${issue.message}`);
      // A file comes from a person's vouched input or a performer, never from the definition (ADR-0008).
      const ref = findBlobRefs(arg, { limit: 0 })[0];
      if (ref) return failAt(st, [...at, ...ref.path], BLOB_LITERAL, BLOB_LITERAL_MESSAGE);
      return { k: "lit", v: arg as JsonValue };
    }
    case "fact":
    case "result": {
      if (!st.allowState) return bad(`"${mainKey}" is not available here; use only frozen data`);
      if (typeof arg !== "string" || arg.length === 0) return bad(`${mainKey} must name a ${mainKey === "fact" ? "fact" : "action"}`);
      const p = raw.path ?? [];
      if (!isPath(p)) {
        st.bag.error("flow/expr-invalid", [...path, "path"], "path must be a list of keys and indexes (at most 16)");
        return null;
      }
      if (mainKey === "fact") {
        if (st.collections.has(arg) && p.length > 0) return failAt(st, at, "flow/collection-path", `a collection is read whole, never by position or path; use map, filter, some or every over fact.${arg}`);
        st.reads.facts.add(arg);
      } else st.reads.results.add(arg);
      return { k: mainKey, name: arg, path: [...p] };
    }
    case "payload":
    case "value":
    case "resource": {
      if (!st.scopes.has(mainKey)) return bad(`"${mainKey}" is not available here`);
      if (!isPath(arg)) return bad(`${mainKey} takes a path (a list of keys and indexes)`);
      return { k: mainKey, path: [...arg] };
    }
    case "item": {
      if (!isPath(arg)) return bad("item takes a path (a list of keys and indexes)");
      if (st.itemDepth === 0) {
        if (st.itemOf === undefined) return bad('"item" only exists inside map, filter, some and every');
        // Outside list operations, the item the expression belongs to.
        const field = arg[0];
        if (typeof field !== "string") return bad(`write item.<field>, a field of "${st.itemOf}" or its id`);
        if (field !== "id") {
          if (!st.collections.get(st.itemOf)?.has(field)) return failAt(st, at, "flow/unknown-fact", `unknown field "${field}" of collection "${st.itemOf}"`);
          (st.reads.self ??= new Set()).add(field);
        }
        return { k: "self", path: [...arg] };
      }
      return { k: "item", path: [...arg] };
    }
    case "items": {
      if (typeof arg !== "string" || arg.length === 0) return bad("items names a collection");
      if (!st.allowItems) return failAt(st, at, "flow/items-view-only", "items gives a list's rows as they stand, for views only; elsewhere read the settled list with fact");
      if (!st.collections.has(arg)) return failAt(st, at, "flow/unknown-fact", `unknown collection "${arg}"`);
      return { k: "items", name: arg };
    }
    case "map":
    case "filter":
    case "some":
    case "every": {
      if (!Array.isArray(arg) || arg.length !== 2) return bad(`${mainKey} takes [list, expression for each item]`);
      const a = parse(arg[0], [...at, 0], st, depth + 1);
      st.itemDepth++;
      const b = parse(arg[1], [...at, 1], st, depth + 1);
      st.itemDepth--;
      return a && b ? { k: mainKey, a, b } : null;
    }
    case "env": {
      if (typeof arg !== "string" || !ENV_NAMES.includes(arg as EnvName)) return bad(`env must be one of ${ENV_NAMES.join(", ")}`);
      return { k: "env", name: arg as EnvName };
    }
    case "now": {
      if (!st.allowNow) return bad('"now" is not allowed here because its value changes on every event');
      if (arg !== true) return bad('write {"now": true}');
      return { k: "now" };
    }
    case "known":
    case "failed": {
      if (!st.allowState) return bad(`"${mainKey}" is not available here; use only frozen data`);
      if (typeof arg !== "string" || arg.length === 0) return bad(`${mainKey} must name a ${mainKey === "known" ? "fact" : "action"}`);
      if (mainKey === "known") st.reads.facts.add(arg);
      else st.reads.results.add(arg);
      return { k: mainKey, name: arg };
    }
    case "if": {
      if (!Array.isArray(arg) || arg.length !== 3) return bad("if takes [condition, then, else]");
      const c = parse(arg[0], [...at, 0], st, depth + 1);
      const t = parse(arg[1], [...at, 1], st, depth + 1);
      const e = parse(arg[2], [...at, 2], st, depth + 1);
      return c && t && e ? { k: "if", c, t, e } : null;
    }
    case "obj": {
      if (!isJsonObject(arg)) return bad("obj takes an object of expressions");
      const entries: [string, Node][] = [];
      for (const [key, value] of Object.entries(arg)) {
        if (key === "__proto__") return bad("key __proto__ is not allowed");
        if (key === BLOB_REF_KEY) return failAt(st, [...at, key], BLOB_LITERAL, BLOB_LITERAL_MESSAGE);
        const n = parse(value, [...at, key], st, depth + 1);
        if (!n) return null;
        entries.push([key, n]);
      }
      return { k: "obj", entries };
    }
    case "param":
      // Replaced by the include's binding when a fragment is expanded (see include.ts).
      return bad('"param" is only available in a fragment, where an include binds it');
    default:
      break;
  }
  if (UNARY.has(mainKey)) {
    const a = parse(arg, at, st, depth + 1);
    return a ? ({ k: mainKey, a } as Node) : null;
  }
  if (BINARY.has(mainKey)) {
    if (!Array.isArray(arg) || arg.length !== 2) return bad(`${mainKey} takes exactly two operands`);
    const a = parse(arg[0], [...at, 0], st, depth + 1);
    const b = parse(arg[1], [...at, 1], st, depth + 1);
    return a && b ? ({ k: mainKey, a, b } as Node) : null;
  }
  if (VARIADIC.has(mainKey)) {
    if (!Array.isArray(arg)) return bad(`${mainKey} takes a list of operands`);
    if (arg.length === 0 && !EMPTY_OK.has(mainKey)) return bad(`${mainKey} needs at least one operand`);
    const items: Node[] = [];
    for (let i = 0; i < arg.length; i++) {
      const n = parse(arg[i], [...at, i], st, depth + 1);
      if (!n) return null;
      items.push(n);
    }
    return { k: mainKey, items } as Node;
  }
  st.bag.error("flow/expr-unknown-operator", at, `unknown operator "${mainKey}"${OBJECT_HINT}`);
  return null;
}

const LEAF_OPERATORS = new Set<string>(EXPR_OPERATORS.leaf);

/** Larger than the JSON form of any expression within the node limit (paths count too). */
const MAX_TEXT_TREE = 32 * MAX_EXPR_NODES;

function jsonCount(value: JsonValue, cap: number): number {
  let n = 0;
  const stack: JsonValue[] = [value];
  while (stack.length > 0 && n <= cap) {
    const v = stack.pop()!;
    n++;
    if (Array.isArray(v)) for (const item of v) stack.push(item);
    else if (isJsonObject(v)) for (const key of Object.keys(v)) stack.push(v[key]!);
  }
  return n;
}

/**
 * Replaces every `{"expr": text}` in an expression with the JSON tree the
 * text compiles to, so what is stored never depends on the text grammar.
 * Works in place where it can and returns the result. Text that does not
 * compile is left for {@link parseExpr} to report; `lit` values are never
 * touched.
 */
export function normaliseExpr(raw: JsonValue): JsonValue {
  if (!isJsonObject(raw)) return raw;
  const keys = Object.keys(raw);
  const op = keys[0];
  if (op === undefined || keys.length !== 1 || op === "__proto__") return raw;
  const arg = raw[op]!;
  if (op === "expr") {
    if (typeof arg !== "string") return raw;
    const text = textToExpr(arg);
    // A tree larger than any valid expression stays text, so the parser reports its size without it being expanded here.
    return text.ok && jsonCount(text.expr as JsonValue, MAX_TEXT_TREE) <= MAX_TEXT_TREE ? cloneJson(text.expr as JsonValue) : raw;
  }
  if (LEAF_OPERATORS.has(op)) return raw;
  if (op === "obj" && isJsonObject(arg)) {
    for (const key of Object.keys(arg)) if (key !== "__proto__") arg[key] = normaliseExpr(arg[key]!);
  } else if (Array.isArray(arg)) {
    for (let i = 0; i < arg.length; i++) arg[i] = normaliseExpr(arg[i]!);
  } else raw[op] = normaliseExpr(arg);
  return raw;
}
